#include "scamptrie_dynamic.h"
#include "image_io.hpp"
#include "mem_init.h"

#include <cstdlib>
#include <iostream>
#include <memory>
#include <stdexcept>
#include <sys/wait.h>
#include <vector>

// One JSON request per process: the fixed front end has already validated the
// request syntax and bounds and converted it to the internal wire format.

int main() {
    try {
        std::ios::sync_with_stdio(false);
        std::cin.tie(nullptr);
        size_t cases = 0;
        if (!(std::cin >> cases)) throw std::runtime_error("wire cases");
        std::cout << "{\"results\":[";
        for (size_t c = 0; c < cases; ++c) {
            if (c) std::cout << ',';
            std::unique_ptr<ScampTrieDynamic> live(new ScampTrieDynamic());
            MemoryImage loaded;
            std::vector<nexthop_t> answers;
            std::vector<ImageData> saved;
            std::vector<bool> loads;
            size_t count = 0;
            if (!(std::cin >> count)) throw std::runtime_error("wire ops");
            for (size_t i = 0; i < count; ++i) {
                char op = 0;
                if (!(std::cin >> op)) throw std::runtime_error("wire opcode");
                if (op == 'P') {
                    ip6_t ip = read_ip();
                    unsigned len = 0;
                    uint64_t hop = 0;
                    if (!(std::cin >> len >> hop)) throw std::runtime_error("wire put");
                    if (live->insert_prefix(ip, static_cast<uint8_t>(len), hop) != SCAMPTRIE_OK)
                        throw std::runtime_error("put failed");
                } else if (op == 'Q' || op == 'I') {
                    size_t n = 0;
                    if (!(std::cin >> n)) throw std::runtime_error("wire query");
                    for (size_t j = 0; j < n; ++j) {
                        ip6_t ip = read_ip();
                        answers.push_back(op == 'Q' ? live->lookup(ip) : loaded.lookup(ip));
                    }
                } else if (op == 'S') {
                    MemInit exporter(live.get());
                    saved.push_back(exporter.capture());
                } else if (op == 'R') {
                    size_t id = 0;
                    if (!(std::cin >> id)) throw std::runtime_error("wire load_saved");
                    if (id >= saved.size()) throw std::runtime_error("saved index");
                    loads.push_back(loaded.load(saved[id]));
                } else if (op == 'L') {
                    ImageData d = image_read_wire();
                    loads.push_back(loaded.load(d));
                } else {
                    throw std::runtime_error("wire opcode");
                }
            }
            std::cout << "{\"answers\":[";
            for (size_t i = 0; i < answers.size(); ++i) {
                if (i) std::cout << ',';
                if (answers[i] == LPM_INVALID_NH) std::cout << "null";
                else std::cout << answers[i];
            }
            std::cout << "],\"snapshots\":[";
            for (size_t i = 0; i < saved.size(); ++i) {
                if (i) std::cout << ',';
                image_write_json(saved[i]);
            }
            std::cout << "],\"loads\":[";
            for (size_t i = 0; i < loads.size(); ++i) {
                if (i) std::cout << ',';
                std::cout << (loads[i] ? "true" : "false");
            }
            std::cout << "]}";
        }
        std::cout << "]}\n";
        std::cout.flush();
        if (const char* feed = std::getenv("SCAMP_FEED_PID")) {
            int status = 0;
            waitpid(static_cast<pid_t>(std::strtol(feed, nullptr, 10)), &status, 0);
        }
        return 0;
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}
